def S(cite, n, design, result, doi, v=True):
    return {"cite": cite, "n": n, "design": design, "result": result,
            "url": ("https://doi.org/" + doi) if doi else "", "doi": doi or "", "verified": v}
def F(id, dom, sub, finding, grade, plain, studies, contra=(), detail="", oq=(), hyp=()):
    return {"id": id, "target_domain": dom, "subdomain": sub, "finding": finding, "grade": grade,
            "plain": plain, "detail": detail, "studies": list(studies), "contradicting": list(contra),
            "hypotheses": list(hyp), "open_questions": list(oq), "test_available": False}

